-- Adds an unpublished owner-review Cookie Policy; existing publications are untouched.
ALTER TABLE legal_versions DROP CONSTRAINT legal_versions_policy_check;
ALTER TABLE legal_versions ADD CONSTRAINT legal_versions_policy_check CHECK(policy IN('privacy','terms','refunds','cookies'));
ALTER TABLE legal_drafts DROP CONSTRAINT legal_drafts_policy_check;
ALTER TABLE legal_drafts ADD CONSTRAINT legal_drafts_policy_check CHECK(policy IN('privacy','terms','refunds','cookies'));
ALTER TABLE legal_policy_state DROP CONSTRAINT legal_policy_state_policy_check;
ALTER TABLE legal_policy_state ADD CONSTRAINT legal_policy_state_policy_check CHECK(policy IN('privacy','terms','refunds','cookies'));
INSERT INTO legal_drafts(policy,html) VALUES('cookies','<h1>Cookie Policy — owner-review draft</h1><p>Owner/legal review required: confirm this inventory against the live release before publication. This is not an approved policy.</p><h2>Authentication</h2><p>Signing in creates the first-party anibish_session cookie. It supports secure account sessions, lasts up to 12 hours and uses Secure, HttpOnly and SameSite=Strict settings in production. Signing out clears it in this browser; server sessions may expire or be revoked sooner.</p><h2>Interface and safety storage</h2><p>The first-party anibish-theme local-storage value remembers your selected interface theme until changed or browser storage is cleared. The anibish_signed_out_locally session-storage marker prevents this browser tab from reopening a workspace after local sign-out; session storage ends with the browsing session.</p><h2>Optional tracking</h2><p>The reviewed application source does not load analytics, advertising tags, tracking pixels or third-party embedded widgets. Confirm production scripts and any provider-added technologies before publication. Optional tracking must not be introduced without a new assessment and any required prior permission.</p><h2>Your controls</h2><p>You can change the theme in the website, sign out, or clear this website’s storage in your browser. Blocking essential session storage may prevent account features from working. Contact mail@anibish.com with questions.</p>');
INSERT INTO legal_policy_state(policy,enabled) VALUES('cookies',false);
